import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { buildPageViewBody, sendPageView } from '../lib/sendPageView';
// Хіт на першу сторінку і на кожну зміну маршруту. Лише в робочій збірці:
// розробка, Storybook і тести лічильник не наповнюють.
export const usePageViewTracking = (enabled = !__IS_DEV__) => {
    const { pathname, search } = useLocation();
    useEffect(() => {
        if (!enabled)
            return;
        sendPageView(buildPageViewBody(pathname, search));
        // search навмисно не в залежностях: зміна лише query — не нова сторінка
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [pathname, enabled]);
};
